// Kiểm mã nhóm, đọc form và dựng sự kiện giống TikTok gửi
const crypto = require('crypto');
const f = $input.first().json;
const fail = (msg) => [{ json: { ok: false, title: 'Chưa gửi được', msg } }];
const expected = $env.GIA_LAP_MA || '';
if (!expected) return fail('Chế độ giả lập đang tắt. Nhờ M3 chạy scripts/gia-lap.sh bat.');
const h = (s) => crypto.createHash('sha256').update(String(s)).digest();
if (!crypto.timingSafeEqual(h(f['Mã nhóm'] || ''), h(expected))) return fail('Sai mã nhóm.');
const VIEC = {
  'Khách đặt đơn mới': 'dat_don',
  'Kho đóng gói xong (thay Odoo báo)': 'dong_goi',
  'Đơn đang giao': 'dang_giao',
  'Khách đã nhận hàng': 'da_giao',
  'Khách hủy đơn': 'huy_don',
};
const viec = VIEC[f['Việc']];
if (!viec) return fail('Chọn một việc.');
let orderId = String(f['Mã đơn'] || '').trim();
let items = [];
if (viec === 'dat_don') {
  items = String(f['Sản phẩm'] || '').split(',').map((s) => s.trim()).filter(Boolean).map((s) => {
    const [sku, n] = s.split('*').map((x) => x.trim());
    return { seller_sku: sku.toUpperCase(), quantity: Math.max(1, parseInt(n, 10) || 1) };
  });
  if (!items.length) return fail('Nhập ít nhất một SKU ở ô Sản phẩm, vd PK-CAP-C2C-1M*2.');
  orderId = '5799' + String(Date.now()).slice(-12) + String(Math.floor(Math.random() * 100)).padStart(2, '0');
} else if (!/^\d{6,}$/.test(orderId)) {
  return fail('Nhập mã đơn (dãy số hiện ra sau khi đặt đơn mới).');
}
const STATUS = { dat_don: 'AWAITING_SHIPMENT', dang_giao: 'IN_TRANSIT', da_giao: 'DELIVERED', huy_don: 'CANCELLED', dong_goi: '' };
const ts = Math.floor(Date.now() / 1000);
const base = { tts_notification_id: 'gialap' + Date.now(), shop_id: 'gia-lap-shop', timestamp: ts };
let event = null;
if (['dat_don', 'dang_giao', 'da_giao'].includes(viec)) {
  event = { type: 1, ...base, data: { order_id: orderId, order_status: STATUS[viec], is_on_hold_order: false, update_time: ts } };
} else if (viec === 'huy_don') {
  event = { type: 11, ...base, data: { order_id: orderId, cancellations_role: 'BUYER', cancel_status: 'CANCELLATION_REQUEST_COMPLETE', update_time: ts } };
}
return [{ json: { ok: true, viec, viec_vi: f['Việc'], order_id: orderId, status: STATUS[viec],
  items: JSON.stringify(items), total: Number(f['Tổng tiền']) || 0, event } }];

// Ký sự kiện như TikTok rồi gửi vào Router, hoặc báo đóng gói vào Đặt vận chuyển như Odoo
const crypto = require('crypto');
const s = $('Kiểm và dựng sự kiện').first().json;
const row = $input.first().json;
if (!row.order_id) {
  return [{ json: { title: 'Không thấy đơn', msg: `Chưa có đơn giả lập ${s.order_id}. Chọn "Khách đặt đơn mới" trước.` } }];
}
let res;
if (s.viec === 'dong_goi') {
  const body = { _model: 'stock.picking', id: 0, name: `WH/OUT/GL${s.order_id.slice(-5)}`, origin: 'GIA-LAP',
    state: 'done', picking_type_code: 'outgoing', client_order_ref: s.order_id };
  res = await this.helpers.httpRequest({
    method: 'POST',
    url: `http://localhost:5678/webhook/odoo-picking-done?secret=${encodeURIComponent($env.ODOO_WEBHOOK_SECRET || '')}`,
    json: true, body, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 20000,
  });
} else {
  const raw = JSON.stringify(s.event);
  const sig = crypto.createHmac('sha256', $env.TIKTOK_APP_SECRET || '').update($env.TIKTOK_APP_KEY || '').update(raw).digest('hex');
  res = await this.helpers.httpRequest({
    method: 'POST', url: 'http://localhost:5678/webhook/tiktok-events',
    headers: { 'Content-Type': 'application/json', Authorization: sig },
    body: raw, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 20000,
  });
}
const NEXT = {
  dat_don: 'Tiếp theo: M2 · Tạo đơn chạy. Khi muốn giao, chọn "Kho đóng gói xong" với mã đơn này.',
  dong_goi: 'Tiếp theo: M3 · Đặt vận chuyển gọi TikTok giả đặt lấy hàng. Sau đó chọn "Đơn đang giao".',
  dang_giao: 'Tiếp theo: M3 · Trạng thái đơn ghi trạng thái và nhắn mã vận đơn cho khách.',
  da_giao: 'Đơn đã giao xong.',
  huy_don: 'Tiếp theo: M2 · Hủy đơn chạy.',
};
const ok = res.statusCode >= 200 && res.statusCode < 300;
return [{ json: {
  title: ok ? `Đã gửi: ${s.viec_vi}` : `Hệ thống trả lỗi ${res.statusCode}`,
  msg: `Mã đơn: ${s.order_id}. ${ok ? NEXT[s.viec] : 'Xem n8n > Executions để biết lỗi.'} Kết quả từng bước xem trong n8n > Executions.`,
} }];
